def f(g):
    H,W=len(g),len(g[0]); bg=g[0][0]
    out=[row[:] for row in g]
    walls=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    # enclosed bg regions: not 4-connected to border through bg
    vis=[[False]*W for _ in range(H)]; q=deque()
    for r in range(H):
        for c in (0,W-1):
            if g[r][c]==bg and not vis[r][c]: vis[r][c]=True; q.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if g[r][c]==bg and not vis[r][c]: vis[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in dset:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and g[nr][nc]==bg and not vis[nr][nc]:
                vis[nr][nc]=True; q.append((nr,nc))
    inner=[(r,c) for r in range(H) for c in range(W) if g[r][c]==bg and not vis[r][c]]
    done=[[False]*W for _ in range(H)]
    for r,c in inner:
        if done[r][c]: continue
        done[r][c]=True; q=deque([(r,c,0)])
        while q:
            rr,cc,dl=q.popleft()
            col=4 if dl%2==1 else 2
            for dr,dc in dset:
                nr,nc=rr+dr,cc+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]==bg and not done[nr][nc]:
                    done[nr][nc]=True; q.append((nr,nc,dl+1))
    # redo: multi-source BFS from walls into inner regions
    done=[[False]*W for _ in range(H)]
    q=deque()
    for r,c in inner:
        # distance from nearest wall
        best=min(abs(r-R)+abs(c-C) for R,C in walls)
        col=4 if best%2==1 else 2
        if not done[r][c]: done[r][c]=True; out[r][c]=col; q.append((r,c,best))
    # propagate: unvisited inner cells get color of nearest visited neighbor with same... 
    # instead: BFS from all walls simultaneously
    done=[[False]*W for _ in range(H)]
    q=deque()
    dist=[[None]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg:
                if not done[r][c]: done[r][c]=True; q.append((r,c,0)); dist[r][c]=0
    while q:
        r,c,d=q.popleft()
        for dr,dc in dset:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and g[nr][nc]==bg and (dist[nr][nc] is None or dist[nr][nc]>d+1):
                dist[nr][nc]=d+1; done[nr][nc]=True; q.append((nr,nc,d+1))
    for r in range(H):
        for c in range(W):
            if g[r][c]==bg and dist[r][c] is not None:
                out[r][c]=4 if dist[r][c]%2==1 else 2
    return out
