def solve(g):
    H,W=len(g),len(g[0]); bg=g[0][0]
    cs=comps_of(g,3); fr=max(cs,key=len)
    vis=[[False]*W for _ in range(H)]; q=deque()
    for r in range(H):
        for c in (0,W-1):
            if g[r][c]==bg and not vis[r][c]: vis[r][c]=True; q.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if g[r][c]==bg and not vis[r][c]: vis[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in dset:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and g[nr][nc]==bg and not vis[nr][nc]:
                vis[nr][nc]=True; q.append((nr,nc))
    out=[row[:] for row in g]
    for R,C in fr:
        out[R][C]=4 if False else 3
    q=deque(list(fr))
    dist={p:0 for p in fr}
    while q:
        r,c=q.popleft()
        for dr,dc in dset:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not vis[nr][nc] and g[nr][nc]==bg:
                dist[(nr,nc)]=dist[(r,c)]+1
                out[nr][nc]=4 if dist[(nr,nc)]%2==1 else 2
                q.append((nr,nc))
    return out
