import numpy as np, json
from collections import deque
def kflood(kg):
    g=np.array(kg); H,W=g.shape
    ws={(i,j) for i in range(H) for j in range(W) if g[i][j]==3}
    tb=min(i for i,_ in ws); bb=max(i for i,_ in ws)
    ll=min(j for _,j in ws); rr=max(j for _,j in ws)
    seeds=[p for p in ws if tb<p[0]<bb and ll<p[1]<rr]
    res=[[4]*W for _ in range(H)]
    seen=set(seeds); q=deque()
    for s in seeds: res[s[0]][s[1]]=2; q.append(s)
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    while q:
        i,j=q.popleft()
        for di,dj in dirs:
            n=(i+di,j+dj)
            if n not in ws and n not in seen and tb<n[0]<bb and ll<n[1]<rr:
                seen.add(n); res[n[0]][n[1]]=2; q.append(n)
    return res
for nm in ['Demo pair 2','Demo pair 3']:
    pr=kflood(G[nm+' input']); o=np.array(G[nm+' output'])
    diff=[(i,j,int(pr[i][j]),int(o[i][j])) for i in range(15) for j in range(15) if pr[i][j]!=o[i][j]]
